<?php declare(strict_types=1);require_once __DIR__.'/_common.php';$error='';$editAlbumId=(int)($_GET['edit_album']??0);$editAlbum=null;if(post()){verifyCsrf();$action=$_POST['action']??'';try{if($action==='album'){ $id=(int)($_POST['id']??0);$title=clean('title',255);$category=clean('category',80);$description=clean('description',3000);if(!$title)throw new RuntimeException('Album title is required.');if($id)db()->prepare('UPDATE gallery_albums SET title=?,category=?,description=? WHERE id=?')->execute([$title,$category,$description,$id]);else db()->prepare('INSERT INTO gallery_albums(title,category,description,created_by) VALUES(?,?,?,?)')->execute([$title,$category,$description,$admin['id']]);flash('success','Album saved.');redirect('gallery.php');}if($action==='image'){ $album=(int)($_POST['album_id']??0);$url=safeFileUpload('image');if(!$url)throw new RuntimeException('Please select an image.');$en=clean('caption_en',255);$fr=clean('caption_fr',255);$ar=clean('caption_ar',255);$category=clean('category',80)?:'General';db()->prepare('INSERT INTO gallery_items(album_id,image_path,caption_en,caption_fr,caption_ar,category,uploaded_by) VALUES(?,?,?,?,?,?,?)')->execute([$album?:null,$url,$en,$fr,$ar,$category,$admin['id']]);flash('success','Image uploaded.');redirect('gallery.php');}if($action==='update_image'){ $id=(int)($_POST['id']??0);$en=clean('caption_en',255);$fr=clean('caption_fr',255);$ar=clean('caption_ar',255);$category=clean('category',80)?:'General';$replacement=safeFileUpload('replace_image');if($replacement){db()->prepare('UPDATE gallery_items SET image_path=?,caption_en=?,caption_fr=?,caption_ar=?,category=? WHERE id=?')->execute([$replacement,$en,$fr,$ar,$category,$id]);}else{db()->prepare('UPDATE gallery_items SET caption_en=?,caption_fr=?,caption_ar=?,category=? WHERE id=?')->execute([$en,$fr,$ar,$category,$id]);}flash('success','Image details updated.');redirect('gallery.php');}if($action==='featured'){$album=(int)$_POST['album_id'];$item=(int)$_POST['item_id'];db()->prepare('UPDATE gallery_albums SET featured_item_id=? WHERE id=?')->execute([$item?:null,$album]);flash('success','Featured image updated.');redirect('gallery.php');}if($action==='delete_image'){$id=(int)$_POST['id'];db()->prepare('DELETE FROM gallery_items WHERE id=?')->execute([$id]);flash('success','Image removed.');redirect('gallery.php');}if($action==='delete_album'){$id=(int)$_POST['id'];db()->prepare('DELETE FROM gallery_albums WHERE id=?')->execute([$id]);flash('success','Album removed.');redirect('gallery.php');}}catch(Throwable $e){error_log($e->getMessage());$error=$e->getMessage();}}$albums=db()->query('SELECT * FROM gallery_albums ORDER BY id DESC')->fetchAll();if($editAlbumId){$q=db()->prepare('SELECT * FROM gallery_albums WHERE id=?');$q->execute([$editAlbumId]);$editAlbum=$q->fetch()?:null;}$items=db()->query('SELECT * FROM gallery_items ORDER BY uploaded_at DESC')->fetchAll();$byAlbum=[];foreach($items as $i)$byAlbum[$i['album_id']][]=$i;$pageTitle='Gallery admin';require dirname(__DIR__).'/includes/header.php';?><section class="section"><div class="container"><p class="eyebrow">Administration</p><h1 class="section-title">Gallery & featured images.</h1><?php if($error):?><div class="flash error" style="position:static;margin:15px 0"><?=e($error)?></div><?php endif;?><div class="grid-3" style="margin-top:30px"><div class="form-shell" style="margin:0"><h2><?=$editAlbum?'Edit album':'Create album'?></h2><form method="post"><?=csrfField()?><input type="hidden" name="action" value="album"><input type="hidden" name="id" value="<?=e((string)($editAlbum['id']??0))?>"><div class="field"><label>Title</label><input name="title" value="<?=e($editAlbum['title']??'')?>" required></div><div class="field"><label>Category</label><input name="category" value="<?=e($editAlbum['category']??'General')?>"></div><div class="field"><label>Description</label><textarea name="description"><?=e($editAlbum['description']??'')?></textarea></div><button class="btn primary"><?=$editAlbum?'Save album':'Create album'?></button><?php if($editAlbum):?><a class="btn ghost" href="gallery.php">Cancel edit</a><?php endif;?></form></div><div class="form-shell" style="margin:0;grid-column:span 2"><h2>Upload image</h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="image"><div class="field"><label>Album</label><select name="album_id"><option value="0">No album</option><?php foreach($albums as $a):?><option value="<?=$a['id']?>"><?=e($a['title'])?></option><?php endforeach;?></select></div><div class="field"><label>Image</label><input type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp" required></div><div class="grid-3"><input name="caption_en" placeholder="Caption EN"><input name="caption_fr" placeholder="Caption FR"><input name="caption_ar" placeholder="Caption AR"></div><div class="field"><label>Category</label><input name="category" value="General"></div><button class="btn coral">Upload</button></form></div></div><div class="grid-3" style="margin-top:30px"><?php foreach($albums as $a):?><div class="card"><div class="card-body"><span class="tag"><?=e($a['category'])?></span><h3><?=e($a['title'])?></h3><p><?=e($a['description'])?></p><a class="btn ghost" href="gallery.php?edit_album=<?=$a['id']?>">Edit album</a><?php $albumItems=$byAlbum[$a['id']]??[];if($albumItems):?><form method="post"><?=csrfField()?><input type="hidden" name="action" value="featured"><input type="hidden" name="album_id" value="<?=$a['id']?>"><div class="field"><label>Featured image</label><select name="item_id"><?php foreach($albumItems as $i):?><option value="<?=$i['id']?>" <?=((int)$a['featured_item_id']===$i['id'])?'selected':''?>>Image #<?=$i['id']?></option><?php endforeach;?></select></div><button class="btn primary">Set featured</button></form><?php endif;?><div style="margin-top:18px"><?php foreach($albumItems as $i):?><div class="gallery-admin-item"><img src="<?=e($i['image_path'])?>" alt=""><details><summary>Edit photo and caption</summary><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="update_image"><input type="hidden" name="id" value="<?=$i['id']?>"><div class="field"><label>Replace image (optional)</label><input type="file" name="replace_image" accept="image/jpeg,image/png,image/gif,image/webp"></div><div class="field"><label>Caption EN</label><input name="caption_en" value="<?=e($i['caption_en']??'')?>"></div><div class="field"><label>Caption FR</label><input name="caption_fr" value="<?=e($i['caption_fr']??'')?>"></div><div class="field"><label>Caption AR</label><input name="caption_ar" value="<?=e($i['caption_ar']??'')?>"></div><div class="field"><label>Category</label><input name="category" value="<?=e($i['category']??'General')?>"></div><button class="btn primary">Save image details</button></form></details><form method="post"><?=csrfField()?><input type="hidden" name="action" value="delete_image"><input type="hidden" name="id" value="<?=$i['id']?>"><button class="btn coral" data-confirm="Delete this image?">Delete</button></form></div><?php endforeach;?></div><form method="post" style="margin-top:10px"><?=csrfField()?><input type="hidden" name="action" value="delete_album"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn ghost" data-confirm="Delete this album and detach its images?">Delete album</button></form></div></div><?php endforeach;?></div></div></section><?php require dirname(__DIR__).'/includes/footer.php';
